const stor = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const smaa = (o, s) => { const x = o(stor(s)); return x === stor(s) ? s : x.toLowerCase(); };
const bare = (o, s) => { const x = o(s); return x !== s ? x : null; };

export const MONSTRE_ES = [
  // Motivos de las sugerencias de cena
  [/^(.+) på tilbud hos (.+?) \((\d+) % billigere\)$/, (m, o) => `${o(m[1])} en oferta en ${m[2]} (${m[3]} % más barato)`],
  [/^(.+) på tilbud hos (.+)$/, (m, o) => `${o(m[1])} en oferta en ${m[2]}`],
  [/^Dere har (.+) og (.+) hjemme$/, (m, o) => `Tienen ${smaa(o, m[1])} y ${smaa(o, m[2])} en casa`],
  // Ofertas
  [/^(\d+) % under vanlig \(~(.+) kr\/(kg|l|stk)\)$/, (m) => `${m[1]} % menos que lo normal (~${m[2]} kr/${m[3] === 'stk' ? 'u.' : m[3]})`],
  [/^−(\d+) % \(før (.+) kr\)$/, (m) => `−${m[1]} % (antes ${m[2]} kr)`],
  // Botones y listas con nombres
  [/^Bytt middag (.+)$/, (m, o) => `Cambiar la cena de ${o(m[1]).toLowerCase()}`],
  [/^Beløp per måned for (.+)$/, (m, o) => `Monto por mes de ${o(m[1])}`],
  [/^Fjern (.+)$/, (m, o) => `Sacar ${o(m[1])}`],
  [/^Endre (.+)$/, (m, o) => `Cambiar ${o(m[1])}`],
  [/^Mindre (.+)$/, (m, o) => `Menos ${o(m[1])}`],
  [/^Mer (.+)$/, (m, o) => `Más ${o(m[1])}`],
  [/^(.+) er tom$/, (m, o) => `Se terminó: ${o(m[1])}`],
  [/^(.+) – ([^–]+)$/, (m, o) => (bare(o, m[1]) ? `${o(m[1])} – ${m[2]}` : null)],
  [/^(.+) \(([^()]+)\)$/, (m, o) => (bare(o, m[1]) ? `${o(m[1])} (${m[2]})` : null)],
  [/^(.+): (\d[\d\s,.]*) kr$/, (m, o) => (bare(o, m[1]) ? `${o(m[1])}: ${m[2]} kr` : null)],
  [/^Fordeling: (.+)$/, (m, o) => `Reparto: ${m[1].split(', ').map((d) => { const x = d.match(/^(.+) (\d[\d\s,.]*) kr$/); return x ? `${o(x[1])} ${x[2]} kr` : d; }).join(', ')}`],
  // Platos y comidas en listas («Taco, Frokost»)
  [/^[^,]+(, [^,]+)+( …)?$/, (m, o) => { const deler = m[0].replace(/ …$/, '').split(', '); const ut = deler.map(o); return ut.every((x, i) => x !== deler[i]) ? ut.join(', ') + (m[2] || '') : null; }],
];
